import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  mix,
  smoothstep,
  vec3,
  vec2,
  fract,
  sin,
  dot,
  texture,
  uniform,
  length,
  clamp,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, CircleGeometry, DirectionalLight, Color } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'pricing-card-3';

  // ---- dimensions (aspect from atlas source rect 512x320) ----
  const aspect = 512 / 320;
  const cardHeight = 1.6;
  const cardWidth = cardHeight * aspect;

  // ---- depth plane 1: subtle backdrop plate behind the card ----
  const backGeo = new PlaneGeometry(cardWidth * 1.12, cardHeight * 1.18);
  const backMat = new MeshBasicNodeMaterial({ transparent: true });
  {
    const surfaceCol = vec3(0.043, 0.043, 0.063);
    const inkCol = vec3(0.086, 0.086, 0.114);
    const g = mix(surfaceCol, inkCol, smoothstep(0.0, 1.0, uv().y));
    backMat.colorNode = g;
    backMat.opacityNode = uniform(0.9);
  }
  const backPlate = new Mesh(backGeo, backMat);
  backPlate.position.z = -0.06;
  root.add(backPlate);

  // ---- depth plane 2: main card surface (engineered gradient + grain) ----
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshPhysicalNodeMaterial({
    roughness: 0.55,
    metalness: 0.4,
    clearcoat: 0.15,
    clearcoatRoughness: 0.35,
    color: new Color(colors.ink),
  });

  const inkColor = vec3(0.086, 0.086, 0.114);
  const surfaceColor = vec3(0.043, 0.043, 0.063);
  const accentColor = vec3(1.0, 0.165, 0.22);

  const gradientTint = mix(surfaceColor, inkColor, smoothstep(0.0, 1.0, uv().y));
  const hash = fract(sin(dot(uv(), vec2(12.9898, 78.233))).mul(43758.5453));
  const grain = hash.mul(0.035).sub(0.0175);
  const grainVec = vec3(grain, grain, grain);
  const bottomGlow = smoothstep(0.08, 0.0, uv().y).mul(0.22);

  let baseColorNode = mix(gradientTint.add(grainVec), accentColor, bottomGlow);
  cardMat.colorNode = baseColorNode;

  const card = new Mesh(cardGeo, cardMat);
  root.add(card);

  // load the real texture and blend it into the surface once ready
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace ?? tex.colorSpace;
    const texColor = texture(tex).rgb;
    const withTex = mix(texColor, gradientTint.add(grainVec), 0.28);
    cardMat.colorNode = mix(withTex, accentColor, bottomGlow);
    cardMat.needsUpdate = true;
  });

  // ---- depth plane 3: foreground accent strip (decorative price highlight) ----
  const stripGeo = new PlaneGeometry(cardWidth * 0.32, cardHeight * 0.03);
  const stripMat = new MeshBasicNodeMaterial({ transparent: true });
  stripMat.colorNode = accentColor;
  stripMat.opacityNode = uniform(0.85);
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(-cardWidth * 0.28, -cardHeight * 0.4, 0.03);
  root.add(strip);

  // ---- radial contact shadow beneath the card ----
  const shadowRadius = cardWidth * 0.75;
  const shadowGeo = new CircleGeometry(shadowRadius, 32);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const d = length(uv().sub(vec2(0.5, 0.5))).mul(2.0);
    const falloff = clamp(smoothstep(1.0, 0.0, d), 0.0, 1.0);
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
    shadowMat.opacityNode = falloff.mul(0.48);
  }
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -cardHeight * 0.62;
  shadow.position.z = 0.001;
  root.add(shadow);

  // ---- node-local rim light (accent tint, within intensity cap) ----
  const rim = new DirectionalLight(new Color(colors.accent), 0.7);
  rim.position.set(-1.2, 0.6, 1.6);
  root.add(rim);

  // ---- entrance motion: weighted-settle ----
  root.scale.setScalar(0.96);
  cardMat.transparent = true;
  cardMat.opacity = 0;
  backMat.opacity = 0;

  const tl = gsap.timeline();
  tl.to(root.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 0.5,
    ease: 'power2.out',
  }).to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  tl.to(
    cardMat,
    { opacity: 1, duration: 0.6, ease: 'power2.out' },
    0
  );
  tl.to(
    backMat,
    { opacity: 0.9, duration: 0.6, ease: 'power2.out' },
    0
  );

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    [cardGeo, backGeo, stripGeo, shadowGeo].forEach((g) => g.dispose());
    [cardMat, backMat, stripMat, shadowMat].forEach((m) => m.dispose());
    root.remove(rim);
  };

  return root;
}
